// Writes dist/.htaccess for IONOS (Apache) hosting: HTTPS + apex host, legacy redirects from
// data/redirects.csv, 410s for retired WordPress endpoints, security headers, caching and the 404 page.
// Runs after every build. Edit data/redirects.csv, not the generated file.

import { readFile, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const draft = process.env.ALLOW_UNREVIEWED === '1';
const csv = await readFile(join(root, 'data', 'redirects.csv'), 'utf8');

const esc = (s) => s.replace(/[.+?^${}()|[\]\\]/g, '\\$&');
/** "/wp-admin/*" -> "^wp-admin/.*$"; "/menus" -> "^menus/?$" (Apache strips the leading slash). */
function pattern(from) {
  const p = from.replace(/^\//, '');
  if (p.endsWith('*')) return `^${esc(p.slice(0, -1))}.*$`;
  return `^${esc(p.replace(/\/$/, ''))}/?$`;
}

const rules = [];
const seen = new Set();
for (const line of csv.split(/\r?\n/)) {
  if (!line.trim() || line.startsWith('#') || line.startsWith('from,')) continue;
  const [from, to, status] = line.split(',').map((s) => s.trim());
  const pat = pattern(from);
  if (seen.has(pat)) continue; // "/menus" and "/menus/" collapse to one rule
  seen.add(pat);
  if (status === '410') rules.push(`RewriteRule ${pat} - [G,L]`);
  else if (status === '404') rules.push(`RewriteRule ${pat} - [R=404,L]`);
  else if (from.replace(/\/$/, '') + '/' === to) continue; // trailing-slash only: handled by Apache's DirectorySlash
  else rules.push(`RewriteRule ${pat} ${to} [R=${status || 301},L]`);
}

const csp = [
  "default-src 'self'",
  "img-src 'self' data:",
  "style-src 'self' 'unsafe-inline'",
  "script-src 'self'",
  "font-src 'self'",
  "connect-src 'self'",
  'frame-src https://www.google.com',
  "form-action 'self'",
  "base-uri 'self'",
  "object-src 'none'",
].join('; ');

const out = `# Generated by scripts/build-htaccess.mjs. Do not edit here: change data/redirects.csv instead.
Options -Indexes
DirectoryIndex index.html
DirectorySlash On
ErrorDocument 404 /404.html

<IfModule mod_rewrite.c>
RewriteEngine On
${draft ? '' : `
# Force HTTPS and the bare domain (maldonspice.co.uk), in one hop.
RewriteCond %{HTTPS} !=on [OR]
RewriteCond %{HTTP_HOST} ^www\\. [NC]
RewriteRule ^(.*)$ https://maldonspice.co.uk/$1 [R=301,L]
`}
# WordPress query-string URLs (?p=123, ?page_id=45) go to the home page.
RewriteCond %{QUERY_STRING} (^|&)(p|page_id)=\\d+ [NC]
RewriteRule ^$ /? [R=301,L]

# Legacy URLs (data/redirects.csv)
${rules.join('\n')}
</IfModule>

<IfModule mod_headers.c>
Header always set X-Content-Type-Options "nosniff"
Header always set Referrer-Policy "strict-origin-when-cross-origin"
Header always set Permissions-Policy "camera=(), microphone=(), geolocation=(), payment=()"
Header always set Content-Security-Policy "${csp}"
${draft ? 'Header always set X-Robots-Tag "noindex, nofollow"' : 'Header always set Strict-Transport-Security "max-age=31536000"'}
<FilesMatch "\\.html$">
Header set Cache-Control "public, max-age=300"
</FilesMatch>
</IfModule>

<IfModule mod_expires.c>
ExpiresActive On
ExpiresByType font/woff2 "access plus 1 year"
ExpiresByType image/avif "access plus 1 year"
ExpiresByType image/webp "access plus 1 year"
ExpiresByType image/jpeg "access plus 1 year"
ExpiresByType text/css "access plus 1 year"
ExpiresByType text/javascript "access plus 1 year"
ExpiresByType application/javascript "access plus 1 year"
</IfModule>

<IfModule mod_deflate.c>
AddOutputFilterByType DEFLATE text/html text/css text/javascript application/javascript application/json image/svg+xml application/xml
</IfModule>

AddType font/woff2 .woff2
AddType image/avif .avif
AddType application/manifest+json .webmanifest
`;

await writeFile(join(root, 'dist', '.htaccess'), out.replace(/\n{3,}/g, '\n\n'));
if (draft) {
  await writeFile(join(root, 'dist', 'robots.txt'), 'User-agent: *\nDisallow: /\n');
}
console.log(`Wrote dist/.htaccess (${rules.length} redirect rules${draft ? ', preview: noindex' : ''}).`);
